    #[invariant]
    pub fn inv_complete(&self) -> bool {
        &&& (forall |i| self.clients.contains_key(i) <==> i < self.num_threads)
        &&& (forall |i| self.slots.contains_key(i) <==> i < self.num_threads)
    }


